  boolean installConnectAttempt(final SolanaRpcWebsocket current, final CompletableFuture<?> attempt) {
    return locked(() -> {
      if (webSocket != current || state != State.CONNECTING || connectFuture != null) {
        return false;
      }
      connectFuture = attempt;
      return true;
    });
  }
